"""Sweep positions/layers/scale over a base vector dict, log results."""
import sys, subprocess, torch, json, tempfile, os, itertools, time

def run(vecs, positions, scale):
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.pt', delete=False) as f:
        torch.save({int(k): v.float() for k, v in vecs.items()}, f.name)
        p = f.name
    try:
        r = subprocess.run(['.venv/bin/python','tools/metric.py','run',p,'--positions',positions,'--scale',str(scale)],
                           capture_output=True, text=True, timeout=900)
        if r.returncode != 0:
            return {'error': r.stderr.strip()[:200]}
        return json.loads(r.stdout)
    finally:
        os.unlink(p)

def main():
    raw = torch.load('/tmp/steer/scratch/v_raw.pt', weights_only=False)
    base = {int(k): v for k,v in raw.items()}
    configs = []
    for L in [16, 20, 24, 26, 28]:
        for scale in [0.1, 0.3, 0.6, 1.0]:
            configs.append((f'L{L}', {L: base[L]}, 'prefix', scale))
    results = []
    for name, vecs, pos, scale in configs:
        d = run(vecs, pos, scale)
        results.append((name, pos, scale, d.get('pass_at_10'), d.get('mean_log10_rank'), d.get('error')))
        print(f"{name} pos={pos} scale={scale}: pass@10={d.get('pass_at_10')} rank={d.get('mean_log10_rank')} err={d.get('error')}", flush=True)
    json.dump(results, open('/tmp/steer/scratch/sweep1.json','w'))

if __name__ == '__main__':
    main()
